/**
 * LiveEventType is the type of a frame on the live WebSocket (GET /live). Every frame is
 * {"type": ..., "data": ...}; a user only receives events about resources they can access.
 */
export const LiveEventTypeHello = "hello";
export const LiveEventTypeRoomMessage = "room.message";
export const LiveEventTypeRoomChanged = "room.changed";
export const LiveEventTypeRoomDeleted = "room.deleted";
export const LiveEventTypeMembersChanged = "room.members";
export const LiveEventTypeAccessChanged = "access.changed";
export const LiveEventTypeAgentPresence = "agent.presence";
export const LiveEventTypeConnectorStatus = "connector.status";
export const LiveEventTypeChatDiscovered = "chat.discovered";
export const LiveEventTypeOutboxStatus = "outbox.status";
export const LiveEventTypeIdentityLinked = "identity.linked";
/**
 * LiveEventTypeIntelligenceChanged carries the new summary of an intelligence whose
 * profile changed.
 */
export const LiveEventTypeIntelligenceChanged = "intelligence.changed";
export const LiveEventTypeLagged = "lagged";
/**
 * Live event types.
 */
export type LiveEventType = typeof LiveEventTypeHello | typeof LiveEventTypeRoomMessage | typeof LiveEventTypeRoomChanged | typeof LiveEventTypeRoomDeleted | typeof LiveEventTypeMembersChanged | typeof LiveEventTypeAccessChanged | typeof LiveEventTypeAgentPresence | typeof LiveEventTypeConnectorStatus | typeof LiveEventTypeChatDiscovered | typeof LiveEventTypeOutboxStatus | typeof LiveEventTypeIdentityLinked | typeof LiveEventTypeIntelligenceChanged | typeof LiveEventTypeLagged;
export type LiveEvent =
  | LiveHello
  | LiveRoomMessage
  | LiveRoomChanged
  | LiveRoomDeleted
  | LiveMembersChanged
  | LiveAccessChanged
  | LiveAgentPresence
  | LiveConnectorStatus
  | LiveChatDiscovered
  | LiveOutboxStatus
  | LiveIdentityLinked
  | LiveIntelligenceChanged
  | LiveLagged;

/**
 * LiveHello is the first frame after the live WebSocket opens.
 */
export interface LiveHello {
  type: typeof LiveEventTypeHello;
  data: HelloData;
}
/**
 * HelloData carries the server time, so clients can correct relative timestamps.
 */
export interface HelloData {
  server_time: string /* RFC 3339 */;
}
/**
 * LiveRoomMessage reports that a message was stored in a room the user can view (LIVE-01).
 */
export interface LiveRoomMessage {
  type: typeof LiveEventTypeRoomMessage;
  data: Message;
}
/**
 * LiveRoomChanged reports that a room was created or updated.
 */
export interface LiveRoomChanged {
  type: typeof LiveEventTypeRoomChanged;
  data: Room;
}
/**
 * LiveRoomDeleted reports that a room was deleted or the user lost access to it.
 */
export interface LiveRoomDeleted {
  type: typeof LiveEventTypeRoomDeleted;
  data: RoomIDData;
}
/**
 * LiveMembersChanged reports that a room's members changed; refetch GET /rooms/{id}/members.
 */
export interface LiveMembersChanged {
  type: typeof LiveEventTypeMembersChanged;
  data: RoomIDData;
}
/**
 * RoomIDData names the room an event is about.
 */
export interface RoomIDData {
  room_id: string;
}
/**
 * LiveAccessChanged reports that sharing of a resource changed; refetch it.
 */
export interface LiveAccessChanged {
  type: typeof LiveEventTypeAccessChanged;
  data: AccessChangedData;
}
/**
 * AccessChangedData names the resource whose grants changed.
 */
export interface AccessChangedData {
  resource_kind: string; // room, agent or connector
  resource_id: string;
}
/**
 * LiveAgentPresence reports that an agent went online or offline (LIVE-04).
 */
export interface LiveAgentPresence {
  type: typeof LiveEventTypeAgentPresence;
  data: AgentPresence;
}
/**
 * AgentPresence is the online state of an agent.
 */
export interface AgentPresence {
  agent_id: string;
  online: boolean;
  last_seen_at?: string /* RFC 3339 */;
}
/**
 * LiveConnectorStatus reports that a connector changed status (LIVE-04, CON-04).
 */
export interface LiveConnectorStatus {
  type: typeof LiveEventTypeConnectorStatus;
  data: ConnectorStatusData;
}
/**
 * ConnectorStatusData is the new status of a connector; LastError has secrets redacted.
 */
export interface ConnectorStatusData {
  connector_id: string;
  status: ConnectorStatus;
  last_error?: string;
}
/**
 * LiveChatDiscovered reports that a connector saw a new chat or refreshed one.
 */
export interface LiveChatDiscovered {
  type: typeof LiveEventTypeChatDiscovered;
  data: Chat;
}
/**
 * LiveOutboxStatus reports that an outbound delivery changed status (LIVE-04).
 */
export interface LiveOutboxStatus {
  type: typeof LiveEventTypeOutboxStatus;
  data: OutboxUpdate;
}
/**
 * OutboxUpdate is an outbox item with the message and room it belongs to.
 */
export interface OutboxUpdate extends OutboxItem {
  room_id: string;
  message_id: string;
}
/**
 * LiveIdentityLinked reports that a chat identity was linked to the user (UI-18).
 */
export interface LiveIdentityLinked {
  type: typeof LiveEventTypeIdentityLinked;
  data: Identity;
}
/**
 * LiveIntelligenceChanged reports that an intelligence the user can see changed its profile
 * (name, handle, bio or avatar); Data is its new summary.
 */
export interface LiveIntelligenceChanged {
  type: typeof LiveEventTypeIntelligenceChanged;
  data: IntelligenceRef;
}
/**
 * LiveLagged reports that the server dropped events for this connection; refetch visible data.
 */
export interface LiveLagged {
  type: typeof LiveEventTypeLagged;
}

